"""Generate Plotter's role CSS, runtime values, and documented numeric tables."""

import json
import re
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
FOUNDATION = ROOT / "assets" / "foundation"
standard = json.loads((FOUNDATION / "standard.json").read_text())
tokens = standard["tokens"]
roles = standard["roles"]


def number(value):
    return f"{value:g}"


css = [
    "/* Generated by scripts/build-standard.py from assets/foundation/standard.json. */",
    "[data-plotter] {\n  stroke: var(--plotter-ink, currentColor);\n}",
    '[data-plotter] [fill="currentColor"] {\n  fill: var(--plotter-ink, currentColor);\n}',
]
for name, role in roles.items():
    width = role["width"]
    opacity = role["opacity"]
    css.append(
        f'[data-plotter] [data-plotter-role="{name}"] {{\n'
        f"  stroke-width: var({width}, {number(tokens[width])});\n"
        f"  opacity: var({opacity}, {number(tokens[opacity])});\n"
        f'  stroke-dasharray: {role["dash"]};\n'
        "}"
    )
role_css = "\n\n".join(css) + "\n"
(FOUNDATION / "roles.css").write_text(role_css)
(FOUNDATION / "standard.mjs").write_text(
    "// Generated by scripts/build-standard.py from standard.json.\n"
    "function freeze(value) {\n"
    "  for (const child of Object.values(value)) {\n"
    '    if (child && typeof child === "object") freeze(child);\n'
    "  }\n"
    "  return Object.freeze(value);\n"
    "}\n\n"
    f"export const standard = freeze({json.dumps(standard, indent=2, ensure_ascii=False)});\n\n"
    f"export const roleCss = {json.dumps(role_css, ensure_ascii=False)};\n"
)

solid_rows = ["primary", "secondary", "dimension", "guide", "grid", "hatch", "section"]
pattern_rows = ["centerline", "hidden", "transfer"]
solid = [
    "| Role | Width | Opacity | Pattern | Use |",
    "| --- | ---: | ---: | --- | --- |",
]
pattern = [
    "| Role | `stroke-dasharray` | Width / opacity | Meaning |",
    "| --- | --- | --- | --- |",
]
for key in solid_rows:
    role = roles[key]
    width = f'{tokens[role["width"]]:.2f}'
    opacity = number(tokens[role["opacity"]]) if tokens[role["opacity"]] == 1 else f'{tokens[role["opacity"]]:.2f}'
    solid.append(f'| {role["label"]} | {width} | {opacity} | Continuous | {role["use"]} |')
for key in pattern_rows:
    role = roles[key]
    width = f'{tokens[role["width"]]:.2f}'
    opacity = f'{tokens[role["opacity"]]:.2f}'
    pattern.append(f'| {role["label"]} | `{role["dash"]}` | {width} / {opacity} | {role["use"]} |')

guide = ROOT / "references" / "drafting-standard.md"
text = guide.read_text()
fills = [
    "| Mark | Fill | Fill opacity | Use |",
    "| --- | --- | ---: | --- |",
    f"| Region highlight | Illustration ink | {number(tokens['--plotter-opacity-highlight'])} | Named intersection, selection, or result |",
]
for name, table in [("stroke-palette", solid), ("line-patterns", pattern), ("fill-palette", fills)]:
    begin = f"<!-- BEGIN GENERATED: {name} -->"
    end = f"<!-- END GENERATED: {name} -->"
    replacement = begin + "\n" + "\n".join(table) + "\n" + end
    text, count = re.subn(re.escape(begin) + r"[\s\S]*?" + re.escape(end), lambda _: replacement, text)
    if count != 1:
        raise ValueError(f"Expected one {name} table marker in {guide}.")
guide.write_text(text)

# The entry file repeats the numbers an agent needs before it opens a reference.
names = {
    "primary": "primary form", "section": "section cut", "secondary": "secondary form",
    "dimension": "dimension", "leader": "leader", "transfer": "transfer",
    "hidden": "hidden, absent, or proposed outline", "hatch": "hatch",
    "guide": "reference guide", "centerline": "centerline", "grid": "grid",
}
widths = {tokens[role["width"]] for role in roles.values()}
if len(widths) != 1:
    raise ValueError("SKILL.md states one stroke width; the standard now has several.")
by_opacity = {}
for key, name in names.items():
    by_opacity.setdefault(tokens[roles[key]["opacity"]], []).append(name)
opacities = "; ".join(
    f"**{number(value)}** {', '.join(by_opacity[value])}" for value in sorted(by_opacity, reverse=True)
)
dashes = "; ".join(
    f"`{roles[key]['dash']}` {label}"
    for key, label in (("centerline", "centerline"), ("hidden", "hidden, absent, or proposed"), ("transfer", "movement or transfer"))
)
geometry = standard["geometry"]
numbers = [
    f"- Every stroke is **{number(widths.pop())}** unit wide.",
    f"- Opacity: {opacities}.",
    f"- Region highlight: `fill-opacity` **{number(tokens['--plotter-opacity-highlight'])}**.",
    f"- Dashes: {dashes}. Everything else is continuous.",
    f"- Arrowhead: two solid **{number(geometry['arrow']['legLength'])}**-unit legs at **{number(geometry['arrow']['angle'])}°**, meeting the shaft’s last dash at the tip.",
    f"- Dimension: **{number(geometry['dimension']['slashExtent'])}**-unit slashes; at least **{number(geometry['dimension']['labelClearance'])}** units clear around every label’s glyphs.",
    f"- Hatch: **{number(geometry['hatch']['edgePitch'])}**-unit pitch along an edge, at −45°.",
]
entry = ROOT / "SKILL.md"
begin, end = "<!-- BEGIN GENERATED: numbers -->", "<!-- END GENERATED: numbers -->"
entry_text, count = re.subn(
    re.escape(begin) + r"[\s\S]*?" + re.escape(end),
    lambda _: begin + "\n" + "\n".join(numbers) + "\n" + end,
    entry.read_text(),
)
if count != 1:
    raise ValueError(f"Expected one numbers marker in {entry}.")
entry.write_text(entry_text)
print("Generated Plotter role CSS, runtime standard, and numeric reference tables.")
